*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
// jackal_11.05.12

scwin.vScrenID = "ULDSTF70023.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y"; // jackal_11.05.12 상장종목 여부 체크 추가
scwin.vChangeBzProcsNo = ""; //사유변경시 최종 지정 업무처리번호 
scwin.vChangeIsuCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //사유변경시 종목코드

scwin.fn_search = function() {
    var url = "/digital/Lstproc.do?method=searchDigitalTradingSuspension";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (rdo_ISUR_CD_1.getValue() == "1") {
        url += "&DIV_IDX=" + 0 + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
            url += "&DIV_IDX=" + 2 + "&TRS_IDX=" + TRS_IDX_SELECT;
        } else {
            url += "&DIV_IDX=" + 1 + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        }
    }
    //alert(url);
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd_List);
};


// 종목선택 팝업호출용
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};


// 종목선택 팝업호출용
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(1);
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.fn_search();
    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        //btn_Reg.disabled = "disabled";

        //btn_Change.disabled = "disabled";

        //btn_Release.disabled = "disabled";

    } else {
        //btn_Reg.disabled = "";

        //btn_Change.disabled = "";

        //btn_Release.disabled = "";

    }
};


// 상장신청인 선택 팝업호출용
scwin.fn_GetParIsur2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};


// 상장신청인 선택 팝업호출용
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(2);
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.fn_search();
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = dts.getCellData(dts.getRowPosition(), "ISUR_CD"); // 발행기관코드값
        arrPar[1] = dts.getCellData(dts.getRowPosition(), "ISU_NM"); // 종목코드명
        arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)			

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            //arrPar[1] = cmb_ISUR_CD.Text; // 발행기관명
            arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[8] = dts.getCellData(dts.getRowPosition(), "TRD_HALT_RELEAS_BZ_PROCS_NO");
    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션

    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 발행기관명
        arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:상장신청인, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:상장신청인, 3:전체)

        } else {
            arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 상장신청인 코드값
            arrPar[1] = $c.stf.getObjectValue(txb_ISUR_NM); // 상장신청인명명
            arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:상장신청인, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = 0; // 지정및해제구분코드
    arrPar[8] = ""; // 지정업무처리번호

};


/**
상장신청인별 매매거래정지 신규
*/
scwin.fn_new_create_frame = async function(arg) {
    /*
    0:관리종목지정
    4:관리종목지정해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_0", "../digital/ULDSTF70024_new.gfm", "신종증권 매매거래정지 지정", 200, 50, 830, 530, "window");
            break;
    }
};




/**
종몰별 관리종목 신규
*/
scwin.fn_newpre_create_frame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    4:관리종목지정해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_0", "../digital/ULDSTF70024.gfm", "신종증권 매매거래정지 지정", 200, 50, 830, 530, "window");
            break;
        case "8":
            await $c.frame.CreateDialogFrame("DLG_1", "../digital/ULDSTF70026.gfm", "신종증권 매매거래정지 사유변경", 200, 5, 830, 780, "window");
            break;
        case "1":
            await $c.frame.CreateDialogFrame("DLG_2", "../digital/ULDSTF70025.gfm", "신종증권 매매거래정지 해제", 200, 50, 820, 620, "window");
            break;
        case "2":
            await $c.frame.CreateDialogFrame("DLG_2", "../digital/ULDSTF70027.gfm", "신종증권 매매거래정지 정지 및 해제", 200, 50, 820, 560, "window");
            break;
    }
};
scwin.fn_get_isurcode = function() {
    //etn발행사
    dts_DigitalInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_DigitalInst.Reset();
};
scwin.fn_changeRadioBtn = function(idx) {
    if (idx == "1") {
        txb_ISUR_CD.setValue("");
        txb_ISUR_NM.setValue("");
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");
    } else if (idx == "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_ISUR_CD_1.setValue("2");
        rdo_ISUR_CD_2.setValue("1");
    }
};



/**
 * 매매거래정지 지정
 */
scwin.fn_Reg = function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    //상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.fn_new_create_frame("0");
    } else {
        //종목 기준
        scwin.vChangeIsuCd = $c.stf.getObjectValue(txb_ISU_CD);
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_trdchange_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "0");
        if (scwin.vChangeBzProcsNo.length == 0) return;
        scwin.fn_newpre_create_frame("0");
    }
};



/**
 * 매매거래정지 사유변경
 */
scwin.fn_Change_new = async function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    var url = "";
    scwin.fn_SetPar = undefined;
    //상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.fn_GetPar = fn_GetParRsnChange2_new;
        url = "../digital/ULDSTF70026_new.gfm";
    } else {
        //종목 기준
        scwin.vChangeIsuCd = $c.stf.getObjectValue(txb_ISU_CD);
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_trdchange_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "8");
        if (scwin.vChangeBzProcsNo.length == 0) return;
        scwin.fn_GetPar = fn_GetParRsnChange;
        url = "../digital/ULDSTF70026.gfm";
    }
    await $c.frame.CreateDialogFrame("DLG_TRD_CHANGE", url, "신종증권 매매거래정지 사유변경", 10, 10, 830, 780, "window");
};


/**
 * 매매거래정지 해제
 */
scwin.fn_Release = async function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    var url = "";
    scwin.fn_SetPar = undefined;
    //상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.vChangeIsuCd = dts.getCellData(dts.getRowPosition(), "ISU_CD");
        scwin.fn_GetPar = fn_GetParRelease2;
        url = "../digital/ULDSTF70025_new.gfm";
    } else {
        //종목 기준
        scwin.vChangeIsuCd = $c.stf.getObjectValue(txb_ISU_CD);
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_trdchange_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "1");
        if (scwin.vChangeBzProcsNo.length == 0) {
            //alert("매매거래정지해제 대상이 아닙니다.");

        }
        scwin.fn_GetPar = fn_GetParRelease;
        url = "../digital/ULDSTF70025.gfm";
    }
    await $c.frame.CreateDialogFrame("DLG_HALT_RELEASE", url, "신종증권 매매거래정지 해제", 10, 10, 820, 620, "window");
};


/**
 * 매매거래정지 지정및해제
 */
scwin.fn_regRelease = async function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    var url = "";
    scwin.fn_SetPar = undefined;
    scwin.fn_GetPar = fn_GetParNew;
    //상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.vChangeIsuCd = dts.getCellData(dts.getRowPosition(), "ISU_CD");
        url = "../digital/ULDSTF70027_new.gfm";
    } else {
        //종목 기준
        scwin.vChangeIsuCd = $c.stf.getObjectValue(txb_ISU_CD);
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_trdchange_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "2");
        if (scwin.vChangeBzProcsNo.length == 0) return;
        url = "../digital/ULDSTF70027.gfm";
    }
    await $c.frame.CreateDialogFrame("DLG_HALT_RELEASE", url, "신종증권 매매거래정지 지정및해제", 10, 10, 820, 560, "window");
};
scwin.fn_GetParRelease = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_NM); // 발행기관코드값
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_CD); // 발행기관명
    arrPar[2] = ""; // 증권그룹ID	
    arrPar[3] = scwin.fr_MktId; // 시장구분코드
    arrPar[4] = ""; // 업무처리번호(신규작성 시 업무처리번호는 없다.)
    arrPar[5] = "4"; // 지정및해제구분코드 , "4" : 해제
    arrPar[6] = scwin.vChangeIsuCd; // 종목코드값
    arrPar[7] = "0"; // 선택 구분(1:종목, 2:발행회사, 3:전체)
    arrPar[8] = scwin.vChangeBzProcsNo; // 지정업무처리번호
    return arrPar.length;
};
scwin.fn_GetParRelease2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 발행기관코드값
    arrPar[1] = ""; // 발행기관명
    arrPar[2] = ""; // 증권그룹ID	
    arrPar[3] = scwin.fr_MktId; // 시장구분코드
    arrPar[4] = ""; // 업무처리번호(신규작성 시 업무처리번호는 없다.)
    arrPar[5] = "4"; // 지정및해제구분코드 , "4" : 해제
    arrPar[6] = ""; // 종목코드값
    arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)
    arrPar[8] = ""; // 지정업무처리번호
    return arrPar.length;
};


/**
 *	종목 기준 사유변경
 */
scwin.fn_GetParRsnChange = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 발행기관코드값
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 발행기관명
    arrPar[2] = ""; // 증권그룹ID	
    arrPar[3] = scwin.fr_MktId; // 시장구분코드
    arrPar[4] = ""; // 업무처리번호(신규작성 시 업무처리번호는 없다.)
    arrPar[5] = "8"; // 지정및해제구분코드 , "8" : 사유변경
    arrPar[6] = scwin.vChangeIsuCd; // 종목코드값
    arrPar[7] = "0"; // 선택 구분(1:종목, 2:발행회사, 3:전체)
    arrPar[8] = scwin.vChangeBzProcsNo; // 지정업무처리번호
    return arrPar.length;
};


/**
 *	상장신청인 기준 사유변경
 */
scwin.fn_GetParRsnChange2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 발행기관코드값
    arrPar[1] = $c.stf.getObjectValue(txb_ISUR_NM); // 발행기관명
    arrPar[2] = ""; // 증권그룹ID	
    arrPar[3] = scwin.fr_MktId; // 시장구분코드
    arrPar[4] = ""; // 업무처리번호(신규작성 시 업무처리번호는 없다.)
    arrPar[5] = "8"; // 지정및해제구분코드 , "8" : 사유변경
    arrPar[6] = scwin.vChangeIsuCd; // 종목코드값
    arrPar[7] = "0"; // 선택 구분(1:종목, 2:발행회사, 3:전체)
    arrPar[8] = scwin.vChangeBzProcsNo; // 지정업무처리번호
    return arrPar.length;
};
scwin.fn_GetParRsnChange2_new = function(arrPar) {
